      "主线 › 第一季 › vol.1-发现奇迹 › 从告别开始 › 7-6\n\n老板把热气腾腾的拉面放在我们面前，是两碗不同的面。\n白起面前是一碗红油拉面，淡黄色的面条，边上有序的放着蒜苗、香菜和切成薄片的牛肉。\n而放在我面前的是一碗清透的拉面，葱花叉烧依序放在边上，还有半个溏心蛋。\n我特别爱吃这家店的清汤面，高中的时候几乎只要早下课就会过来排队。\n奇怪的是，老板怎么知道我的口味？好像从进来到现在我什么都没提过……\n那唯一的可能就是……\n我抬起头，看了看白起。他正埋头吃面，几缕头发垂在眼前，氤氲的雾气使他整个人看起来都柔和了不少。",
      "约会 › 传闻秘事 › 第二季 › 并肩同行\n\n白起是这里的熟客，老板熟络地招待了上来。他的目光飞速从菜单上扫过，清了清略感不适的嗓子，正准备点一碗辣油面。话至一半，清风吹着街角的风铃作响，将女孩笑吟吟的叮嘱卷入脑海——嗓子不好不要吃辣，清汤味道也不错。\n白起怔了一瞬，正准备抓住这突如其来的回忆，老板的笑脸在面前晃了晃。\n“还是老规矩，吃辣油的吗？”\n白起想了想，最终还是摇摇头，“今天要清汤的吧。”\n“白警官今天改口了啊，好呦。”老板有些惊讶，笑着调侃，“清汤面一碗，稍等就来。”",
      "讯息 › 朋友圈 › 陪伴朋友圈 › 2023年4月 限时忌口\n\n白起 ：距离下次可以吃麻辣汤面，还有3天18小时。\n[玩家姓名] ：牙龈肿了就别想吃辣了，乖乖吃我煮的清汤面~\n白起 回复 [玩家姓名] ： 那……能不能加两根辣条，在汤里泡一下就不辣了，我就尝个鲜。",
      "主线 › 第二季 › vol.12-蒙昧时代 › 回归线 › 41-2--噩梦\n\n我和白起坐在常坐的位置上，没过多久，老板便端着两碗热腾腾的面走来。\n老板： 清汤面和特级辣油面，都是改良的口味。\n老板： 多吃点别客气！如果有什么吃不惯的，也记得和我说\n我看着眼前量多到快溢出大碗的面，哭笑不得。\n白起： 没事，吃不完还有我。\n热腾腾的蒸汽给清冷的夜色平添几分烟火气，我悄悄抬起头，看向白起。\n他正喝了一口辣汤，琥珀色的眼瞳氤氲在雾气里，透出一股由内而外的幸福。"
