      "讯息 › 朋友圈 › 周常朋友圈 › 4.27-5.3 咖喱饭\n\n白起 ：今天的“咖喱饭”，原来是“嘎喱饭”。\n[玩家姓名] ：举手）那个“小鸭子米饭”不是模具压的，是我亲手捏出来的~\n白起 回复 [玩家姓名] ： 看出来了，毕竟模具压不出这么可爱的。\n[玩家姓名] ：完美的小鸭子造型下，隐藏的可是地狱级辣度的咖喱调味料一一采访感受！\n白起 回复 [玩家姓名] ： 还行，大概是地狱的“守门鸭”级别。\n[玩家姓名] ：怎么样，是不是好看又好吃qvq\n白起 回复 [玩家姓名] ： 当然，申请再加一只“小鸭”进入餐盘战场。"
