      "杂篇 › 活动剧情 › 拿卡剧情 › sr › sr-自远方来\n\n“……嗯。”白起又不知道该说什么了，他低头看了看自己咬的包子，又看向诗人。\n“我吃饱了来的，这是偷偷给你带的，里面还有辣粉条的呢。我记得上次训练完，你一口气吃了五个！”\n“咳，那天是饿过头了。”\n白起有些不好意思地解释了一句，莫名地，两个人不约而同地笑了起来。"
