      "约会 › 约会剧情 › er › 犬训之约\n\n[玩家姓名]： 白起，你自己吃饭都没有这么荤素搭配过。\n白起： 没有吧……我很久没有挑食了。\n白起： 你昨晚拌的黄瓜，我不是都吃完了？\n[玩家姓名]： 不是因为你喜欢吃凉拌黄瓜？\n白起： 那你改天拌个苦瓜我一样会吃完的。\n我于是顺手拿了个用保鲜膜盖好的苦瓜丢进了购物车。\n白起： ……",
      "约会 › 约会剧情 › ssr › 标记之约\n\n小奶油： 狼哥哥这么威风也害怕吃苦瓜吗？\n我拼命忍住上翘的嘴角，听着白起一本正经地说着自己挑食的黑历史。\n白起： 嗯，特别是小的时候，看见苦瓜就想跑。又苦又不下饭，但因为营养丰富，有时总会被哄着吃。\n小奶油： 我妈妈也是！总想哄我吃苦瓜。\n小奶油小大人似的拍了拍白起的胳膊，两个“不爱苦瓜”人士之间似乎瞬间产生了一种莫名的惺惺相惜。\n白起： 但我现在已经不怕苦瓜了。\n小奶油： 为什么？\n白起摸了摸小奶油的头顶，半蹲下去和他平视。\n白起： 因为男子汉都不怕吃苦。\n听了这话，小奶油有点动摇了，白起见此继续趁热打铁。\n白起： 其实苦瓜也没有做错什么，它营养丰富，只是味道不太好。\n小奶油： 我要长到和大哥哥一样大，才能成为男子汉吗？\n白起： 不用那么晚，不挑食就是成为男子汉的第一步。\n白起： 而且，男子汉可不能因为讨厌苦瓜就嫌弃自己的好朋友。\n小奶油低头想了想，最后郑重地点了点头。\n小奶油： 我这就去找他。\n见小奶油飞奔到角落的身影，我笑嘻嘻地凑到了白起身边。\n[玩家姓名]： 很不错嘛，“不怕苦瓜的男子汉”先生？\n[玩家姓名]： 但上周和顾征他们一起吃饭的时候，那盘苦瓜你可是一筷子都没动呢。",
      "讯息 › 朋友圈 › 周常朋友圈 › 12.12-12.18 苦瓜小花\n\n白起 ：今天的便当盒里居然发现了两片小花形状的苦瓜。\n[玩家姓名] ：都成了这个形状居然还能被发现吗？\n白起 回复 [玩家姓名] ： 开始时没发现，放到嘴前鼻子闻出来的。\n[玩家姓名] ：白警官居然都吃完了，奖励两朵小花！\n白起 回复 [玩家姓名] ： 不会是再奖励两朵苦瓜小花吧？\n[玩家姓名] ：其实它们只是用来做点缀的啦！\n白起 回复 [玩家姓名] ： 顺便试试能不能骗我吃下去？",
