      "杂篇 › 活动剧情 › 拿卡剧情 › ssr › ssr-寄长风\n\n白起： 这位姑娘，可否告诉我你为什么不开心？\n我忍笑板起脸，顺着白起的话开口。\n[玩家姓名]： 因为和我相伴的人用失踪来吓唬我。\n白起： 那如果他将剩下的时间都用来补偿你，你会开心一些吗？\n[玩家姓名]： 那就要看是什么样的补偿了。\n白起勾起唇角，放下面具，揽住我的腰朝空中飞去。\n[玩家姓名]： 红烧鱼……\n[玩家姓名]： 这就是你说的补偿吗？\n热闹的酒楼里，白起坐在靠窗的桌边，用筷子夹起一片鱼肉放到我碗里。\n白起： 尝尝看。\n他斜倚在窗边，双眸含笑望我。\n白起： 上次没能吃成的鱼，这次补给你。\n[玩家姓名]： 好好吃！\n[玩家姓名]： 你怎么会知道这么好吃的红烧鱼？\n白起： 有一年七夕，我路过人间，好奇他们为何这样热闹，就来转了一圈。那时无意中尝到了这道菜，觉得很好吃，但周围都是结伴而来的男女，我却无人可分享。\n他的唇畔露出微微笑意，看我的目光清亮而柔和。\n白起： 现在，我有了可分享的人。"
