      "杂篇 › 活动剧情 › 夏日活动 › 2026逐夏音浪 › 烟火港湾\n\n就在这时，白起见缝插针地递过来两小盘拌好的蟹柳丝。我夹起一筷，蟹柳丝入口鲜甜，裹着微酸的柠檬酱汁，在腾腾热气中格外清爽。\n[玩家姓名]： 哇——好吃，我们菜单上有这个口味吗？\n白起： 没有，是不小心加错酱的，我改良了一下。如果喜欢吃辣，可以加辣油。"
