      "杂篇 › 活动剧情 › 周年活动 › 三周年-愿岁相守 › 恋爱嘉年华\n\n员工： 只要通过了我们的“情侣默契大考验”，就\n白起： ……没关系，下一题我们会答对的。\n白起握住我的手，朝餐桌扬了扬下巴。\n白起： 刚才看菜单时，你不是一直说想吃那道菜吗？\n我顺着白起的视线看去，发现下一道菜果然是这家店的人气菜品——中西结合的面包鸡！光是想到它咸香的味道，我就忍不住咽了咽口水。看着白起坚定而自信的目光，我点了点头。\n[玩家姓名]： 嗯！\n员工： 那么，考验的最后一道题——\n员工： 钢琴还是吉他？\n[玩家姓名]： 吉他！\n白起： 钢琴。\n[玩家姓名]： ……\n员工： 很可惜，两位答案不一样。这道菜我要拿走了。\n工作人员边说边准备将菜端到推车上，白起却忽然伸手拦住。\n白起： 可以换一道吗？\n利落快速的动作让工作人员懵了一下，他顿了半秒，点点头。\n员工： 可、可以，不过有个条件。\n员工： 你们要握着手，看着对方的眼睛，相互表达一下歉意。\n我们听后愣了一下。虽然觉得有些难为情，但我和白起还是握住了对方的手。在这种气氛下，我们四目相对，都有些不好意思。\n[玩家姓名]： 那个……我先说吧。我觉得……第一题答错是我的不对。以后一定会按时吃早餐，不睡懒觉。欢迎白警官监督。嗯，到你了。\n白起： 咳，我……我不该故意失误，答错题……大不了等会不吃就行了。\n[玩家姓名]： ……嗯？\n白起： ……我吃。\n员工： 咳咳——可以了可以了。\n一旁的工作人员打断了我们，口中发出“啧啧”的声音。\n员工： 再看下去，这狗粮都快把我喂饱了！\n我和白起对视一眼，然后又默契地笑出声来。\n像是一阵微风吹到心中最柔软的地方，只觉得此刻无比美好。"
