      "讯息 › 电话 › 羁绊解锁 › 0084 消夏饮品\n\n白起： 我路过了一家甜品铺子。招牌上写着，今日有新品荔枝冻。想试试吗？\n[玩家姓名] ：荔枝冻！听起来和夏天很配！那就麻烦白警官带一个啦~\n白起： 好。还需要别的什么吗？梅渍小番茄，蜜桃波波……\n[玩家姓名] ：这么多我们两个人也吃不完呀。不过听你这么一念，我就每个都想试试……\n白起： 没关系。昨天听你说冰箱空了。刚好今天买一些填进去。\n[玩家姓名] ：好吧，那我就和冰箱一起等你回来啦~\n白起： 嗯，很快。"
