      "约会 › 约会剧情 › sr › 激流之约\n\n[玩家姓名]： 上次我一个人排队就惨了……\n白起： 嗯？\n[玩家姓名]： 我本来是想排队买炒酸奶的，结果不知道怎么走着走着排错队了，最后买到了半只酱板鸭！\n白起： 那你比顾征好点，他上次也是排错了队，本来想去献血，结果莫名其妙登记成了他们小区的社区志愿者……"
