      "约会 › 约会剧情 › ssr › 驰骋之约\n\n等我们在镇上逛到尽兴，驱车前往住处时，已经是夕阳西下。\n[玩家姓名]： 那个久仰大名的柑橘汁意大利面，味道虽然很奇特，但是真的不错。\n白起： 明天中午再去一次？\n[玩家姓名]： 嗯……还是算了，我想试试之前路过的那家店，就是门口挂了火腿和烟熏奶酪的。\n夕阳把天际的积雨云染成柔和的暖色。我们有一句没一句地闲聊，悠然行驶在公路上。"
