      "约会 › 约会剧情 › ssr › 培训之约\n\n天地间重要的，只有我眼前的他，和我们将抵达的下一个目的地。民宿在朝海边的方向开了一扇大大的落地窗。海天相接，似乎随时都能浸入长风，自由地浮空翱翔。除了景色，另一样我同样自信的安排则是——\n[玩家姓名]： 锵锵！虽然不健康但是绝对好吃的垃圾食品套餐！\n[玩家姓名]： 压力过后，就是应该享受啤酒和高热量食品！我买了炸鸡和披萨，味道应该不错。\n[玩家姓名]： 尝尝看？"
